167	  uintptr_t max = ((x ^ (x >> 17)) & 0x0F) + 1;
168	  for (uintptr_t i = 0; i < max || x==0; i++, x++) {
169	    x = _mi_random_shuffle(x);
170	  }
171	  mi_assert_internal(x != 0);
172	  return x;
173	}
