175	static void mi_random_init_ex(mi_random_ctx_t* ctx, bool use_weak) {
176	  uint8_t key[32];
177	  if (use_weak || !_mi_prim_random_buf(key, sizeof(key))) {
178	    // if we fail to get random data from the OS, we fall back to a
179	    // weak random source based on the current time
180	    #if !defined(__wasi__)
181	    if (!use_weak) { _mi_warning_message("unable to use secure randomness\n"); }
182	    #endif
183	    uintptr_t x = _mi_os_random_weak(0);
184	    for (size_t i = 0; i < 32; i+=4, x++) {  
