186	      key[i]   = (uint8_t)(x);
187	      key[i+1] = (uint8_t)(x>>8);
188	      key[i+2] = (uint8_t)(x>>16);
189	      key[i+3] = (uint8_t)(x>>24);      
190	    }
191	    ctx->weak = true;
192	  }
193	  else {
194	    ctx->weak = false;
195	  }
196	  chacha_init(ctx, key, (uintptr_t)ctx /*nonce*/ );
197	  _mi_memzero(key, sizeof(key));
198	}
199	
200	void _mi_random_init(mi_random_ctx_t* ctx) {
201	  mi_random_init_ex(ctx, false);
202	}
203	
204	void _mi_random_init_weak(mi_random_ctx_t * ctx) {
205	  mi_random_init_ex(ctx, true);
206	}
207	
208	void _mi_random_reinit_if_weak(mi_random_ctx_t * ctx) {
209	  if (ctx->weak) {
210	    _mi_random_init(ctx);
211	  }
212	}
