221	// Free a block
222	// Fast path written carefully to prevent register spilling on the stack
223	static mi_decl_forceinline void mi_free_nonnull(void* p, mi_page_t* page, size_t* pblock_size, bool allow_collect)  
224	{
225	  mi_assert_internal(p!=NULL && page!=NULL);
226	  if (pblock_size!=NULL) { *pblock_size = mi_page_block_size(page); }
227	
228	  const mi_threadid_t ptid = mi_page_xthread_id(page);
229	  const mi_threadid_t xtid = (_mi_prim_thread_id() ^ ptid);
230	  if mi_likely(xtid == 0) {                        // `tid == mi_page_thread_id(page) && mi_page_flags(page) == 0`
231	    // thread-local, aligned, and not a full page
232	    mi_block_t* const block = mi_validate_block_from_ptr(page,p);
233	    mi_free_block_local(page, block, false /* was guarded */, true /* track stats */, false /* no need to check if the page is full */);
234	  }
235	  else if (xtid <= MI_PAGE_FLAG_MASK) {            // `tid == mi_page_thread_id(page) && mi_page_flags(page) != 0`
236	    // page is local, but is full or contains (inner) aligned blocks; use generic path
237	    mi_free_generic_local(page, p);
238	  }
239	  // free-ing in a page owned by a theap in another thread, or an abandoned page (not belonging to a theap)
240	  else if ((xtid & MI_PAGE_FLAG_MASK) == 0) {      // `tid != mi_page_thread_id(page) && mi_page_flags(page) == 0`
241	    // blocks are aligned (and not a full page); push on the thread_free list
242	    mi_block_t* const block = mi_validate_block_from_ptr(page,p);
243	    mi_free_block_mt(page,block,false /* was_guarded */, allow_collect);
244	  }
245	  else {
246	    // page is full or contains (inner) aligned blocks; use generic multi-thread path
247	    mi_free_generic_mt(page, p, allow_collect);
248	  }
249	}
