310	void mi_free_size(void* p, size_t size) mi_attr_noexcept {
311	  MI_UNUSED_RELEASE(size);
312	  #if MI_DEBUG
313	    const mi_page_t* const page = mi_validate_ptr_page(p,"mi_free_size");
314	    if (page==NULL) return;
315	    mi_assert(p!=NULL);
316	    const size_t usable = _mi_page_usable_size(page,p);
317	    if mi_unlikely(size > usable) { 
318	      _mi_error_message(EINVAL, "pointer %p is freed with mi_free_size but the size %zu is greater than the usable size %zu\n", p, size, usable);
319	      mi_free(p);
320	      return;
321	    }
322	    else if mi_unlikely(size <= MI_SMALL_SIZE_MAX && mi_page_block_size(page) > mi_good_size(MI_SMALL_SIZE_MAX)) { 
323	      _mi_error_message(EINVAL, "pointer %p is freed with mi_free_size but the given size %zu is less than the allocated block size %zu\n", p, size, mi_page_block_size(page));
324	      mi_free(p);
325	      return;
326	    }
327	  #endif
328	  #if MI_PAGE_META_SMALL_IS_ALIGNED
329	  if mi_likely(size <= MI_SMALL_SIZE_MAX) {
330	    mi_free_small(p); 
331	  }
332	  else 
333	  #endif
334	  {
335	    mi_free(p);
336	  }
337	}
