625	// Extend the capacity (up to reserved) by initializing a free list
626	// We do at most `MI_MAX_EXTEND` to avoid touching too much memory
627	// Note: we also experimented with "bump" allocation on the first
628	// allocations but this did not speed up any benchmark (due to an
629	// extra test in malloc? or cache effects?)
630	static bool mi_page_extend_free(mi_theap_t* theap, mi_page_t* page) {
631	  mi_assert_expensive(mi_page_is_valid_init(page));
632	  #if (MI_SECURE < 2)
633	  mi_assert(page->free == NULL);
634	  mi_assert(page->local_free == NULL);
635	  if (page->free != NULL) return true;
636	  #endif
637	  if (page->capacity >= page->reserved) return true;
638	
639	  size_t page_size;
640	  //uint8_t* page_start =
641	  mi_page_area(page, &page_size);
642	  #if MI_STAT>0
643	  mi_theap_stat_counter_increase(theap, pages_extended, 1);
644	  #endif
645	
646	  // calculate the extend count
647	  const size_t bsize = mi_page_block_size(page);
648	  size_t extend = (size_t)page->reserved - page->capacity;
649	  mi_assert_internal(extend > 0);
650	
651	  size_t max_extend = (bsize >= MI_MAX_EXTEND_SIZE ? MI_MIN_EXTEND : MI_MAX_EXTEND_SIZE/bsize);
652	  if (max_extend < MI_MIN_EXTEND) { max_extend = MI_MIN_EXTEND; }
653	  mi_assert_internal(max_extend > 0);
654	
655	  if (extend > max_extend) {
656	    // ensure we don't touch memory beyond the page to reduce page commit.
657	    // the `lean` benchmark tests this. Going from 1 to 8 increases rss by 50%.
658	    extend = max_extend;
659	  }
660	
661	  mi_assert_internal(extend > 0 && extend + page->capacity <= page->reserved);
662	  mi_assert_internal(extend < (1UL<<16));
663	
664	  // commit on demand?
665	  const size_t slice_committed = mi_page_slice_committed(page);
666	  if (slice_committed > 0) {
667	    // reduce extend if it commits more than an arena slice
668	    if ((extend * bsize) > MI_ARENA_SLICE_SIZE) {
669	      extend = _mi_divide_up(MI_ARENA_SLICE_SIZE, bsize);
670	    }
671	    // commit required size
672	    const size_t needed_size = (page->capacity + extend)*bsize;
673	    mi_assert_internal(needed_size <= page_size);
674	    size_t needed_commit = _mi_align_up( mi_page_slice_offset_of(page, needed_size), mi_page_min_commit_size());
675	    #if MI_SECURE>=5
676	    // the previous alignup could extend the commit into the guard page; re-adjust if needed
677	    const size_t page_size_commit = _mi_align_up( mi_page_slice_offset_of(page, page_size), _mi_os_page_size() );    
678	    if (needed_commit > page_size_commit) { 
679	      needed_commit = page_size_commit;
680	    }
681	    #endif
682	    if (needed_commit > slice_committed) {
683	      mi_assert_internal(((needed_commit - slice_committed) % _mi_os_page_size()) == 0);
684	      if (!_mi_os_commit(_mi_theap_subproc(theap), mi_page_slice_start(page) + slice_committed, needed_commit - slice_committed, NULL)) {
685	        return false;
686	      }
687	      mi_assert_internal(needed_commit <= UINT16_MAX * _mi_os_page_size());
688	      page->slice_pcommitted = (uint16_t)(needed_commit / _mi_os_page_size());
689	    }
690	  }
691	
692	  // and append the extend the free list
693	  if (extend < MI_MIN_SLICES || MI_SECURE<2) { //!mi_option_is_enabled(mi_option_secure)) {
694	    mi_page_free_list_extend(page, bsize, extend );
695	  }
696	  else {
697	    mi_page_free_list_extend_secure(theap, page, bsize, extend);
698	  }
699	  // enable the new free list
700	  page->capacity += (uint16_t)extend;
701	  #if MI_STAT>0
702	  mi_theap_stat_increase(theap, page_committed, extend * bsize);
703	  #endif
704	  mi_assert_expensive(mi_page_is_valid_init(page));
705	  return true;
706	}
